instrumentation.after:
this.store.event("paste_written", { dispatch: item.id }, pane.record);
if (pane.record.cli === "Codex" && !existsSync("/private/tmp/t258-gp511nli/out/paused.json")) {
  if (!pane.leader) throw new Error("T258 probe requires observed CLI leader");
  const before = { time: new Date().toISOString(), pane_status: this.status(pane.record.thread), shell_pid: pane.pty.pid };
  process.kill(pane.leader, "SIGSTOP");
  writeFileSync("/private/tmp/t258-gp511nli/out/paused.json", JSON.stringify({ pid: pane.leader, launch: pane.record.id, time: new Date().toISOString(), before,
    after: { time: new Date().toISOString(), pane_status: this.status(pane.record.thread) } }), { flag: "wx" });
}
